/* Digitalisierte Arbeitsaufträge aus der ursprünglichen Stationenarbeit. */
const mappingTasks={
planDiagram:{station:0,title:'1. Beschrifte das Planungsschaubild',intro:'Beschrifte zuerst die drei Akteure A, B und C direkt im Schaubild. Wähle danach an jeder Verbindung, was in Pfeilrichtung weitergegeben wird. Jeder Begriff wird einmal verwendet.',options:['Zentrale','Unternehmen','Haushalte','Arbeitsleistung','Konsumgüter','Informationen über Produktion und Verteilung','Informationen über Arbeits- und Konsumwünsche','Anweisung und Kontrolle'],items:[['A: Wer erstellt den Plan?',0],['B: Wer stellt Güter her?',1],['C: Wer arbeitet und konsumiert?',2],['Von A zu B und C',7],['Von B zu A',5],['Von C zu A',6],['Von C zu B',3],['Von B zu C',4]],why:'Die Zentrale erhält Informationen und gibt Vorgaben. Zwischen Unternehmen und Haushalten fließen Arbeitsleistungen und Konsumgüter. Die Pfeile zeigen hier reale Leistungen und Informationen, keine vollständigen Geldströme.'},
pillars:{station:2,title:'1. Die zwei Säulen der Marktwirtschaft',intro:'Ergänze das Schaubild aus dem Arbeitsblatt. Wähle den jeweils passenden Mechanismus.',options:['Eigeninteresse / Eigennutz','Preismechanismus','Zentrale Produktionsvorgaben','Garantierter Gewinn'],items:[['Antrieb: Menschen verfolgen eigene wirtschaftliche Ziele.',0],['Koordination: Angebot und Nachfrage werden auf Märkten abgestimmt.',1]],why:'Eigeninteresse schafft Anreize; der Preismechanismus verbindet dezentrale Entscheidungen. Das bedeutet nicht, dass Eigennutz automatisch allen Menschen nützt.'},
marketProblems:{station:3,title:'1. Ergänze das Schaubild: mögliche Schwächen',intro:'Ordne jeder Situation den passenden Begriff zu. Die Aussagen beschreiben mögliche Probleme einer freien Marktwirtschaft, keine unvermeidbaren Ergebnisse.',options:['Negative externe Effekte','Öffentliche Güter','Ungleiche Kaufkraft / soziale Unsicherheit','Krisenanfälligkeit'],items:[['Ein Betrieb verursacht Schäden bei Dritten, die im Preis nicht vollständig berücksichtigt werden.',0],['Ein gemeinsamer Schutz, von dem niemand leicht ausgeschlossen werden kann, wird durch freiwillige Zahlungen zu wenig finanziert.',1],['Eine Familie kann nötige Güter wegen geringen Einkommens nicht bezahlen.',2],['In einem Abschwung sinken Produktion und Beschäftigung.',3]],why:'Die fachlichen Kategorien helfen beim Vergleich. Bildung und U-Bahnfahrten sind nicht automatisch reine öffentliche Güter. Bei reinen öffentlichen Gütern sind Ausschluss kaum möglich und die Nutzung nicht rivalisierend.'}
};
function mappingHTML(id){if(id==='planDiagram')return planDiagramHTML();const t=mappingTasks[id];return `<section class="original-task" aria-labelledby="title-${id}"><p class="eyebrow">Aus deinem Arbeitsblatt · digital überarbeitet</p><h3 id="title-${id}">${t.title}</h3><p>${t.intro}</p>${id==='pillars'?'<div class="diagram-key"><strong>Marktwirtschaft</strong><span>Zwei Säulen: Antrieb + Koordination</span></div>':''}${t.items.map(([label],i)=>`<div class="mapping-row"><label for="mapping-${id}-${i}">${label}</label><select id="mapping-${id}-${i}" data-mapping="${id}" data-item="${i}"><option value="">Begriff auswählen …</option>${t.options.map((o,n)=>`<option value="${n}" ${state.tasks[id]?.values?.[i]===n?'selected':''}>${esc(o)}</option>`).join('')}</select><span id="mapping-hint-${id}-${i}" class="small"></span></div>`).join('')}<button class="secondary" data-check-mapping="${id}">Zuordnung prüfen</button><div id="mapping-feedback-${id}" role="status">${state.tasks[id]?.checked?mappingFeedback(id):''}</div></section>`;}
function mappingCorrect(id){return mappingTasks[id].items.every((item,i)=>state.tasks[id]?.values?.[i]===item[1]);}
function mappingFeedback(id){const t=mappingTasks[id];const correct=t.items.filter((item,i)=>state.tasks[id]?.values?.[i]===item[1]).length;return `<div class="feedback ${correct===t.items.length?'good':''}"><strong>${correct} von ${t.items.length} Zuordnungen richtig.</strong>${correct===t.items.length?t.why:'Überarbeite die markierten Zuordnungen. Nutze bei Bedarf den Lesetext in „Verstehen“.'}</div>`;}
function originalPractice(station){return Object.entries(mappingTasks).filter(([,t])=>t.station===station).map(([id])=>mappingHTML(id)).join('');}
function originalsMissing(station){return Object.entries(mappingTasks).some(([id,t])=>t.station===station&&(!state.tasks[id]?.checked||!mappingCorrect(id)));}
function exerciseExport(){return `<h2>Meine Zuordnungen aus den Arbeitsblättern</h2>${Object.entries(mappingTasks).map(([id,t])=>`<h3>${t.title}</h3><ul>${t.items.map(([label],i)=>`<li><strong>${esc(label)}</strong>: ${esc(t.options[state.tasks[id]?.values?.[i]]??'Noch nicht beantwortet')}</li>`).join('')}</ul>`).join('')}`;}
document.addEventListener('change',e=>{const el=e.target,id=el.dataset.mapping;if(!id)return;const record=state.tasks[id]??{values:{},checked:false};record.values[el.dataset.item]=el.value===''?null:Number(el.value);record.checked=false;state.tasks[id]=record;invalidate(mappingTasks[id].station);document.querySelectorAll(`[data-mapping="${id}"]`).forEach(s=>s.removeAttribute('aria-invalid'));document.querySelectorAll(`[id^="mapping-hint-${id}-"]`).forEach(s=>s.textContent='');$('#mapping-feedback-'+id).innerHTML='';if(id==='planDiagram')refreshPlanDiagram();save();});
document.addEventListener('click',e=>{const id=e.target.closest('button')?.dataset.checkMapping;if(!id)return;state.tasks[id]??={values:{},checked:false};state.tasks[id].checked=true;mappingTasks[id].items.forEach((item,i)=>{const right=state.tasks[id].values[i]===item[1];const select=$(`#mapping-${id}-${i}`);select.setAttribute('aria-invalid',String(!right));select.setAttribute('aria-describedby',`mapping-hint-${id}-${i}`);$(`#mapping-hint-${id}-${i}`).textContent=right?'Richtig zugeordnet.':'Diese Zuordnung bitte noch einmal prüfen.';});$('#mapping-feedback-'+id).innerHTML=mappingFeedback(id);save();});
